 ctx.fillStyle=shirt;ctx.beginPath();ctx.moveTo(-18,-45);ctx.lineTo(14,-46);ctx.quadraticCurveTo(28,-21,22,5);ctx.lineTo(-21,5);ctx.quadraticCurveTo(-25,-20,-18,-45);ctx.fill();
